// ❌ OLD: Hand-rolled enter/exit with CSS classes. You must add the
// class, wait for animationend, remove the element for exits, handle
// rapid toggles (interrupting an animation), and keep the CSS in sync
// with the JS.
function enter(el) {
  el.classList.add('fade-in'); // ❌ OLD: relies on matching CSS
}

function exit(el) {
  el.classList.add('fade-out');
  el.addEventListener('animationend', () => el.remove(), { once: true });
  // ❌ OLD: manual removal timing; rapid toggles can double-fire or
  // leave the element stuck mid-animation.
}

/* CSS must be hand-written separately:
   .fade-in { animation: fade-in 300ms ease; }
   .fade-out { animation: fade-out 300ms ease; } */
